export function getFieldMappingSummary(mapping: FieldMapping | undefined, t: Translate): string {
  if (!mapping?.identifier) {
    return t("setting.sso.mapping-none");
  }

  const parts = [`${t("setting.sso.mapping-identifier-short")}=${mapping.identifier}`];
  if (mapping.displayName) {
    parts.push(`${t("setting.sso.mapping-display-name-short")}=${mapping.displayName}`);
  }
  if (mapping.email) {
    parts.push(`${t("setting.sso.mapping-email-short")}=${mapping.email}`);
  }
  if (mapping.avatarUrl) {
    parts.push(`${t("setting.sso.mapping-avatar-short")}=${mapping.avatarUrl}`);
  }
  return parts.join(" ?? ");
}

function UpdateAccountDialog({ open, onOpenChange, onSuccess }: Props) {
  const t = useTranslate();
  const currentUser = useCurrentUser();
  const { setCurrentUser } = useAuth();
  const { generalSetting: instanceGeneralSetting } = useInstance();
  const { mutateAsync: updateUser } = useUpdateUser();
  const [state, setState] = useState<State>({
    avatarUrl: currentUser?.avatarUrl ?? "",
    username: currentUser?.username ?? "",
    displayName: currentUser?.displayName ?? "",
    email: currentUser?.email ?? "",
    description: currentUser?.description ?? "",
  });

  const handleCloseBtnClick = () => {
    onOpenChange(false);
  };

  const setPartialState = (partialState: Partial<State>) => {
    setState((state) => {
      return {
        ...state,
        ...partialState,
      };
    });
  };

  const handleAvatarChanged = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      const image = files[0];
      if (image.size > 2 * 1024 * 1024) {
        toast.error("Max file size is 2MB");
        return;
      }
      try {
        const base64 = await convertFileToBase64(image);
        setPartialState({
          avatarUrl: base64,
        });
      } catch (error) {
        console.error(error);
        toast.error(`Failed to convert image to base64`);
      }
    }
  };

  const handleDisplayNameChanged = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPartialState({
      displayName: e.target.value as string,
    });
  };

  const handleUsernameChanged = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPartialState({
      username: e.target.value as string,
    });
  };

  const handleEmailChanged = (e: React.ChangeEvent<HTMLInputElement>) => {
    setState((state) => {
      return {
        ...state,
        email: e.target.value as string,
      };
    });
  };

  const handleDescriptionChanged = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setState((state) => {
      return {
        ...state,
        description: e.target.value as string,
      };
    });
  };

  const handleSaveBtnClick = async () => {
    if (state.username === "") {
      toast.error(t("message.fill-all"));
      return;
    }

    try {
      const updateMask = [];
      if (!isEqual(currentUser?.username, state.username)) {
        updateMask.push("username");
      }
      if (!isEqual(currentUser?.displayName, state.displayName)) {
        updateMask.push("display_name");
      }
      if (!isEqual(currentUser?.email, state.email)) {
        updateMask.push("email");
      }
      if (!isEqual(currentUser?.avatarUrl, state.avatarUrl)) {
        updateMask.push("avatar_url");
      }
      if (!isEqual(currentUser?.description, state.description)) {
        updateMask.push("description");
      }
      const updatedUser = await updateUser({
        user: {
          name: currentUser?.name,
          username: state.username,
          displayName: state.displayName,
          email: state.email,
          avatarUrl: state.avatarUrl,
          description: state.description,
        },
        updateMask,
      });
      setCurrentUser(updatedUser);
      toast.success(t("message.update-succeed"));
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      await handleError(error, toast.error, {
        context: "Update account",
      });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{t("setting.account.update-information")}</DialogTitle>
        </DialogHeader>
        <div className="flex flex-col gap-4">
          <div className="flex flex-row items-center gap-2">
            <Label>{t("common.avatar")}</Label>
            <label className="relative cursor-pointer hover:opacity-80">
              <UserAvatar className="w-10 h-10" avatarUrl={state.avatarUrl} />
              <input type="file" accept="image/*" className="absolute invisible w-full h-full inset-0" onChange={handleAvatarChanged} />
            </label>
            {state.avatarUrl && (
              <XIcon
                className="w-4 h-auto cursor-pointer opacity-60 hover:opacity-80"
                onClick={() =>
                  setPartialState({
                    avatarUrl: "",
                  })
                }
              />
            )}
          </div>
          <div className="grid gap-2">
            <Label htmlFor="username">
              {t("common.username")}
              <span className="text-sm text-muted-foreground ml-1">({t("setting.account.username-note")})</span>
            </Label>
            <Input
              id="username"
              value={state.username}
              onChange={handleUsernameChanged}
              disabled={instanceGeneralSetting.disallowChangeUsername}
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="displayName">
              {t("common.nickname")}
              <span className="text-sm text-muted-foreground ml-1">({t("setting.account.nickname-note")})</span>
            </Label>
            <Input
              id="displayName"
              value={state.displayName}
              onChange={handleDisplayNameChanged}
              disabled={instanceGeneralSetting.disallowChangeNickname}
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="email">
              {t("common.email")}
              <span className="text-sm text-muted-foreground ml-1">({t("setting.account.email-note")})</span>
            </Label>
            <Input id="email" type="email" value={state.email} onChange={handleEmailChanged} />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="description">{t("common.description")}</Label>
            <Textarea id="description" rows={2} value={state.description} onChange={handleDescriptionChanged} />
          </div>
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={handleCloseBtnClick}>
            {t("common.cancel")}
          </Button>
          <Button onClick={handleSaveBtnClick}>{t("common.save")}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

const UserMenu = (props: Props) => {
  const { collapsed } = props;
  const t = useTranslate();
  const navigateTo = useNavigateTo();
  const currentUser = useCurrentUser();
  const { userGeneralSetting, refetchSettings, logout } = useAuth();
  const { mutate: updateUserGeneralSetting } = useUpdateUserGeneralSetting(currentUser?.name);
  const sseStatus = useSSEConnectionStatus();
  const currentLocale = getLocaleWithFallback(userGeneralSetting?.locale);
  const currentTheme = getThemeWithFallback(userGeneralSetting?.theme);

  const handleLocaleChange = async (locale: Locale) => {
    if (!currentUser) return;
    // Apply locale immediately for instant UI feedback and persist to localStorage
    loadLocale(locale);
    // Persist to user settings
    updateUserGeneralSetting(
      { generalSetting: { locale }, updateMask: ["locale"] },
      {
        onSuccess: () => {
          refetchSettings();
        },
      },
    );
  };

  const handleThemeChange = async (theme: string) => {
    if (!currentUser) return;
    // Apply theme immediately for instant UI feedback
    loadTheme(theme);
    // Persist to user settings
    updateUserGeneralSetting(
      { generalSetting: { theme }, updateMask: ["theme"] },
      {
        onSuccess: () => {
          refetchSettings();
        },
      },
    );
  };

  const handleSignOut = async () => {
    // First, clear auth state and cache BEFORE doing anything else
    await logout();

    try {
      // Then clear user-specific localStorage items
      // Preserve app-wide settings (theme, locale, view preferences, tag view settings)
      const keysToPreserve = ["memos-theme", "memos-locale", "memos-view-setting", "tag-view-as-tree", "tag-tree-auto-expand"];
      const keysToRemove: string[] = [];

      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && !keysToPreserve.includes(key)) {
          keysToRemove.push(key);
        }
      }

      keysToRemove.forEach((key) => localStorage.removeItem(key));
    } catch {
      // Ignore errors from localStorage operations
    }

    // Always redirect to auth page (use replace to prevent back navigation)
    window.location.replace(Routes.AUTH);
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        nativeButton={false}
        disabled={!currentUser}
        render={
          <div
            className={cn("w-auto flex flex-row justify-start items-center cursor-pointer text-foreground", collapsed ? "px-1" : "px-3")}
          />
        }
      >
        <div className="relative shrink-0">
          {currentUser?.avatarUrl ? (
            <UserAvatar avatarUrl={currentUser?.avatarUrl} />
          ) : (
            <User2Icon className="w-6 mx-auto h-auto text-muted-foreground" />
          )}
          {sseStatus !== "connected" && (
            <Tooltip>
              <TooltipTrigger
                render={
                  <span
                    className={cn(
                      "absolute -bottom-0.5 -right-0.5 size-2.5 rounded-full border-2 border-background",
                      sseStatus === "connecting" ? "bg-muted-foreground animate-pulse" : "bg-destructive",
                    )}
                  />
                }
              />
              <TooltipContent side="right">{t(`live-update.${sseStatus}` as Parameters<typeof t>[0])}</TooltipContent>
            </Tooltip>
          )}
        </div>
        {!collapsed && (
          <span className="ml-2 text-lg font-medium text-foreground grow truncate">
            {currentUser?.displayName || currentUser?.username}
